-- Paket özetleri: panel "A01: 100 kod, 37 boşta" diyebilsin.
create or replace function public.magnet_package_summary()
returns table (
  package_code text,
  total integer,
  free integer,
  assigned integer,
  disabled integer
)
language sql
stable
security definer
set search_path = public
as $$
  select c.package_code,
         count(*)::integer,
         count(*) filter (where c.tenant_id is null)::integer,
         count(*) filter (where c.tenant_id is not null)::integer,
         count(*) filter (where c.is_disabled)::integer
    from public.magnet_codes c
   where c.package_code is not null
   group by c.package_code
   order by c.package_code;
$$;

revoke all on function public.magnet_package_summary() from public;

-- Paket ataması: paketteki SAHİPSİZ kodların tamamını tek ifadede bayiye
-- verir. for update skip locked: iki admin aynı anda atarsa kod paylaşılmaz.
-- Daha önce başka bayiye atanmış kodlara DOKUNMAZ (kutudan eksik çıkanlar
-- panelde "atanmış" olarak görünür, sayı dönüşte belli olur).
create or replace function public.assign_magnet_package(
  p_tenant_id uuid,
  p_package_code text
)
returns integer
language plpgsql
security definer
set search_path = public
as $$
declare
  v_assigned integer;
begin
  if p_package_code is null or btrim(p_package_code) = '' then
    raise exception 'paket kodu gerekli';
  end if;

  with secilen as (
    select id from public.magnet_codes
     where tenant_id is null
       and package_code = p_package_code
       for update skip locked
  )
  update public.magnet_codes c
     set tenant_id = p_tenant_id,
         assigned_at = now()
    from secilen
   where c.id = secilen.id;

  get diagnostics v_assigned = row_count;
  return v_assigned;
end;
$$;

revoke all on function public.assign_magnet_package(uuid, text) from public;

notify pgrst, 'reload schema';
